// Checks for the third-party files: SHA256SUMS names every file of vendor/ and fonts/ with its SHA-256, and
// SBOM.json names every third-party part with the NTIA minimum elements, a licence and a hash that still match.
// After changing a third-party file, run: node tools/sbom.mjs
// Run: npm test (Node 18+).
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { PARTS, checkSupply, listFiles } from '../tools/sbom.mjs';

const APP = fileURLToPath(new URL('..', import.meta.url));

test('SBOM.json and SHA256SUMS match the files', async () => {
  assert.deepEqual(await checkSupply(), []);
});

test('every file of vendor/ and fonts/ has its SHA-256 in SHA256SUMS (checked here on its own)', async () => {
  const sums = new Map((await readFile(join(APP, 'SHA256SUMS'), 'utf8')).trim().split(/\r?\n/).map((l) => [l.slice(66), l.slice(0, 64)]));
  const files = await listFiles();
  assert.ok(files.length >= 15);
  for (const f of files) assert.equal(sums.get(f), createHash('sha256').update(await readFile(join(APP, f))).digest('hex'), f);
});

test('each third-party part names its supplier, version, identifier, licence and hash, and the program depends on it', async () => {
  const sbom = JSON.parse(await readFile(join(APP, 'SBOM.json'), 'utf8'));
  assert.equal(sbom.bomFormat, 'CycloneDX');
  assert.equal(sbom.specVersion, '1.6');
  assert.match(sbom.serialNumber, /^urn:uuid:[0-9a-f-]{36}$/);
  assert.ok(Number.isFinite(Date.parse(sbom.metadata.timestamp)));
  assert.ok(sbom.metadata.authors[0].name.includes('Claude'));
  assert.equal(sbom.components.length, PARTS.length);
  for (const c of sbom.components) {
    assert.ok(c.supplier.name && c.name && c.version && c.purl, c['bom-ref']);
    assert.ok(c.licenses.length, c['bom-ref']);
    assert.ok(c.hashes.every((h) => /^[0-9a-f]+$/.test(h.content)), c['bom-ref']);
  }
  const app = sbom.dependencies.find((d) => d.ref === 'app');
  assert.deepEqual([...app.dependsOn].sort(), PARTS.map((p) => p.ref).sort());
  assert.doesNotMatch(JSON.stringify(sbom), /[\u2013\u2014]/, 'no long dashes');
});
